// Alinx AC7100B on the OCP-TAP Time Card, PCIe x4 Gen1 endpoint: the Vivado 7-series core
// (module-renamed copy pcie_2_1_ep_7x generated by vivado_impl.tcl from the root port example)
// with pci_eerie in place of PCIE_2_1, and the 4 KB BAR0 memory app of the testbench.
// LEDs: 0 user_lnk_up, 1..3 negotiated width (x1/x2/x4).
// JTAG (eerie_jtag_bus, tools/eerie_host.tcl rd 300): any address reads
// {21'd0, width[2:0], 1'b0, lnk_up, ltssm[5:0]} (width: PL initial link width code).
`timescale 1ns / 1ps
module top_ac7100b_x4 #(
    parameter LANES = 4
) (
    output [LANES-1:0] pci_exp_txp, output [LANES-1:0] pci_exp_txn,
    input  [LANES-1:0] pci_exp_rxp, input  [LANES-1:0] pci_exp_rxn,
    input  sys_clk_p, input sys_clk_n,
    input  sys_rst_n,
    output [3:0] led
);
    wire uclk, lnk_up; wire [5:0] ltssm; wire [2:0] width;
    eerie_tb_ep_ml #(.LANES(LANES), .ENABLE_GEN2(0), .GT_DEVICE("GTP"), .FAST_TRAIN("FALSE")) ep (
        .user_clk_o(uclk), .user_lnk_up_o(lnk_up), .ltssm_o(ltssm), .width_o(width),
        .pci_exp_txp(pci_exp_txp), .pci_exp_txn(pci_exp_txn), .pci_exp_rxp(pci_exp_rxp), .pci_exp_rxn(pci_exp_rxn),
        .sys_clk_p(sys_clk_p), .sys_clk_n(sys_clk_n), .sys_rst_n(sys_rst_n)
    );
    wire req, we; wire [15:0] addr; wire [31:0] wdata; wire [31:0] ctl;
    reg  ack = 1'b0; reg [31:0] rdata = 32'd0;
    always @(posedge uclk) begin ack <= req; rdata <= {21'd0, width, 1'b0, lnk_up, ltssm}; end
    eerie_jtag_bus jtag (
        .clk(uclk), .req(req), .we(we), .addr(addr), .wdata(wdata), .rdata(rdata), .ack(ack),
        .aux({7'd0, lnk_up, 2'd0}), .ctl(ctl)
    );
    // LEDs are active low on the AC7100B
    assign led = ~{width == 3'd3, width == 3'd2, width == 3'd1, lnk_up};
endmodule
